/**
 * User-state schema, as ordered migrations in code. `migrate()` applies the pending ones in one
 * transaction under an advisory lock (several gateway processes may start at once) and records them
 * in `schema_migrations`. A database whose schema is newer than this build refuses to start.
 *
 * Conventions: ids are UUIDs generated by the server; times are timestamptz; per-user rows cascade
 * on user deletion. Secrets are never stored in clear: session tokens as SHA-256 hashes, Discord
 * webhook URLs AES-256-GCM encrypted (alerts/secretBox.ts), and no private keys anywhere: trading
 * wallets are public keys and labels only (SPEC "Custody").
 */
import { iso, type PgDriver, toInt } from "./driver";

export interface Migration {
  version: number;
  name: string;
  up: string;
}

/** Arbitrary constant: pg_advisory_xact_lock key for migrations. */
const MIGRATION_LOCK = 7_428_301;

export const MIGRATIONS: readonly Migration[] = [
  {
    version: 1,
    name: "accounts, settings, alerts, audit log",
    up: `
      -- Identity: the connected (main) wallet that signed in with SIWS.
      CREATE TABLE users (
        id UUID PRIMARY KEY,
        wallet TEXT NOT NULL UNIQUE,
        created_at TIMESTAMPTZ NOT NULL,
        last_login_at TIMESTAMPTZ NOT NULL
      );

      -- Sessions: only the SHA-256 of the cookie token is stored; a database leak yields no live session.
      CREATE TABLE sessions (
        id UUID PRIMARY KEY,
        token_hash TEXT NOT NULL UNIQUE,
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        created_at TIMESTAMPTZ NOT NULL,
        expires_at TIMESTAMPTZ NOT NULL,
        last_seen_at TIMESTAMPTZ NOT NULL,
        user_agent_hash TEXT,
        revoked_at TIMESTAMPTZ
      );
      CREATE INDEX sessions_user_id ON sessions (user_id);
      CREATE INDEX sessions_expires_at ON sessions (expires_at);

      -- Trading wallets: public keys and labels only. The keys stay encrypted in the user's browser.
      -- Kept minimal on purpose (SPEC "Insider risk": main-wallet-to-trading-wallet mapping).
      CREATE TABLE trading_wallets (
        id UUID PRIMARY KEY,
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        public_key TEXT NOT NULL,
        label TEXT NOT NULL DEFAULT '',
        created_at TIMESTAMPTZ NOT NULL,
        UNIQUE (user_id, public_key)
      );

      CREATE TABLE presets (
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        slot SMALLINT NOT NULL CHECK (slot BETWEEN 1 AND 3),
        name TEXT NOT NULL,
        config JSONB NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL,
        PRIMARY KEY (user_id, slot)
      );

      CREATE TABLE settings (
        user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,
        data JSONB NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL
      );

      CREATE TABLE watchlist (
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        mint TEXT NOT NULL,
        added_at TIMESTAMPTZ NOT NULL,
        PRIMARY KEY (user_id, mint)
      );

      CREATE TABLE blacklists (
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        kind TEXT NOT NULL CHECK (kind IN ('token', 'dev', 'funder', 'x')),
        value TEXT NOT NULL,
        note TEXT NOT NULL DEFAULT '',
        added_at TIMESTAMPTZ NOT NULL,
        PRIMARY KEY (user_id, kind, value)
      );

      CREATE TABLE tracked_wallets (
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        address TEXT NOT NULL,
        label TEXT NOT NULL DEFAULT '',
        emoji TEXT NOT NULL DEFAULT '',
        tags JSONB NOT NULL DEFAULT '[]'::jsonb,
        alert_buy BOOLEAN NOT NULL DEFAULT false,
        alert_sell BOOLEAN NOT NULL DEFAULT false,
        alert_create BOOLEAN NOT NULL DEFAULT false,
        alert_min_sol DOUBLE PRECISION NOT NULL DEFAULT 0,
        created_at TIMESTAMPTZ NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL,
        PRIMARY KEY (user_id, address)
      );
      -- The alert engine loads the union of alerting wallets (SPEC: match the firehose in memory).
      CREATE INDEX tracked_wallets_alerting ON tracked_wallets (address) WHERE alert_buy OR alert_sell OR alert_create;

      -- Server-evaluated alerts (price, market cap). params / channels are validated JSON.
      CREATE TABLE alerts (
        id UUID PRIMARY KEY,
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        type TEXT NOT NULL,
        params JSONB NOT NULL,
        channels JSONB NOT NULL,
        priority TEXT NOT NULL CHECK (priority IN ('high', 'normal', 'low')),
        repeat TEXT NOT NULL CHECK (repeat IN ('once', 'rearm')),
        cooldown_sec INTEGER NOT NULL,
        enabled BOOLEAN NOT NULL DEFAULT true,
        armed BOOLEAN NOT NULL DEFAULT true,
        note TEXT NOT NULL DEFAULT '',
        last_fired_at TIMESTAMPTZ,
        fire_count INTEGER NOT NULL DEFAULT 0,
        created_at TIMESTAMPTZ NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL
      );
      CREATE INDEX alerts_user_id ON alerts (user_id);
      CREATE INDEX alerts_enabled ON alerts (type) WHERE enabled;

      -- Web Push subscriptions (endpoint host checked against the known push services before storing).
      CREATE TABLE push_subscriptions (
        id UUID PRIMARY KEY,
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        endpoint TEXT NOT NULL UNIQUE,
        p256dh TEXT NOT NULL,
        auth TEXT NOT NULL,
        user_agent_hash TEXT,
        created_at TIMESTAMPTZ NOT NULL,
        last_success_at TIMESTAMPTZ,
        failure_count INTEGER NOT NULL DEFAULT 0
      );
      CREATE INDEX push_subscriptions_user_id ON push_subscriptions (user_id);

      -- Telegram chat links and Discord webhooks. A Telegram row starts 'pending' with the SHA-256 of a
      -- one-time /start code; the bot activates it. Discord webhook URLs are encrypted at rest
      -- (AES-256-GCM with CHANNEL_ENCRYPTION_KEY); target_hint is a masked form for display.
      CREATE TABLE notification_channels (
        id UUID PRIMARY KEY,
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        kind TEXT NOT NULL CHECK (kind IN ('telegram', 'discord')),
        label TEXT NOT NULL DEFAULT '',
        status TEXT NOT NULL CHECK (status IN ('pending', 'active', 'disabled')),
        telegram_chat_id TEXT,
        telegram_link_code_hash TEXT UNIQUE,
        telegram_link_expires_at TIMESTAMPTZ,
        discord_webhook_enc BYTEA,
        discord_webhook_hash TEXT,
        target_hint TEXT NOT NULL DEFAULT '',
        last_error TEXT,
        failure_count INTEGER NOT NULL DEFAULT 0,
        created_at TIMESTAMPTZ NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL,
        CHECK (kind <> 'discord' OR discord_webhook_enc IS NOT NULL)
      );
      CREATE INDEX notification_channels_user_id ON notification_channels (user_id);
      CREATE UNIQUE INDEX notification_channels_user_chat ON notification_channels (user_id, telegram_chat_id)
        WHERE telegram_chat_id IS NOT NULL;
      CREATE UNIQUE INDEX notification_channels_user_hook ON notification_channels (user_id, discord_webhook_hash)
        WHERE discord_webhook_hash IS NOT NULL;
      CREATE INDEX notification_channels_chat ON notification_channels (telegram_chat_id) WHERE telegram_chat_id IS NOT NULL;

      -- One row per alert per message it went out in (digest_count > 1 = batched).
      CREATE TABLE alert_deliveries (
        id UUID PRIMARY KEY,
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        alert_id UUID REFERENCES alerts(id) ON DELETE SET NULL,
        source TEXT NOT NULL,
        channel TEXT NOT NULL,
        target_id UUID,
        priority TEXT NOT NULL,
        status TEXT NOT NULL CHECK (status IN ('sent', 'failed', 'dropped')),
        title TEXT NOT NULL,
        digest_count INTEGER NOT NULL DEFAULT 1,
        error TEXT,
        created_at TIMESTAMPTZ NOT NULL
      );
      CREATE INDEX alert_deliveries_user_time ON alert_deliveries (user_id, created_at DESC);
      CREATE INDEX alert_deliveries_created_at ON alert_deliveries (created_at);

      -- SPEC "Insider risk": every admin action and lookup, append-only (UPDATE, DELETE and TRUNCATE
      -- raise). A database superuser can still drop the trigger; ship this table to off-box storage too.
      CREATE TABLE admin_audit_log (
        id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
        at TIMESTAMPTZ NOT NULL,
        actor TEXT NOT NULL,
        action TEXT NOT NULL,
        target TEXT,
        ip TEXT,
        user_agent_hash TEXT,
        ok BOOLEAN NOT NULL,
        detail JSONB NOT NULL DEFAULT '{}'::jsonb
      );
      CREATE INDEX admin_audit_log_at ON admin_audit_log (at);
      CREATE INDEX admin_audit_log_action ON admin_audit_log (action, at);
      CREATE FUNCTION admin_audit_log_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
      BEGIN
        RAISE EXCEPTION 'admin_audit_log is append-only';
      END
      $$;
      CREATE TRIGGER admin_audit_log_no_change BEFORE UPDATE OR DELETE ON admin_audit_log
        FOR EACH ROW EXECUTE FUNCTION admin_audit_log_append_only();
      CREATE TRIGGER admin_audit_log_no_truncate BEFORE TRUNCATE ON admin_audit_log
        FOR EACH STATEMENT EXECUTE FUNCTION admin_audit_log_append_only();

      -- Schema placeholders for the Phase 5 armed-orders engine. Only the orders topic snapshot reads
      -- armed_orders today; nothing writes either table yet.
      CREATE TABLE nonce_slots (
        id UUID PRIMARY KEY,
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        trading_wallet_id UUID NOT NULL REFERENCES trading_wallets(id) ON DELETE CASCADE,
        nonce_account TEXT NOT NULL UNIQUE,
        seed TEXT NOT NULL,
        status TEXT NOT NULL DEFAULT 'free' CHECK (status IN ('creating', 'free', 'reserved', 'consumed', 'closed')),
        nonce_value TEXT,
        created_at TIMESTAMPTZ NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL
      );
      CREATE INDEX nonce_slots_user_id ON nonce_slots (user_id);

      CREATE TABLE armed_orders (
        id UUID PRIMARY KEY,
        user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        trading_wallet_id UUID REFERENCES trading_wallets(id) ON DELETE SET NULL,
        nonce_slot_id UUID REFERENCES nonce_slots(id) ON DELETE SET NULL,
        kind TEXT NOT NULL,
        status TEXT NOT NULL,
        mint TEXT NOT NULL,
        side TEXT NOT NULL CHECK (side IN ('buy', 'sell')),
        amount TEXT NOT NULL,
        trigger JSONB NOT NULL,
        signed_variants BYTEA,
        cancel_tx BYTEA,
        signature TEXT,
        error TEXT,
        created_at TIMESTAMPTZ NOT NULL,
        updated_at TIMESTAMPTZ NOT NULL
      );
      CREATE INDEX armed_orders_user_id ON armed_orders (user_id);
      CREATE INDEX armed_orders_live ON armed_orders (mint) WHERE status IN ('armed', 'triggered', 'submitted');
    `,
  },
];

export interface MigrateResult {
  applied: number[];
  version: number;
}

/** Applies pending migrations in order, atomically. Safe to call on every start. */
export async function migrate(db: PgDriver, migrations: readonly Migration[] = MIGRATIONS, now = Date.now): Promise<MigrateResult> {
  const known = migrations.reduce((max, m) => Math.max(max, m.version), 0);
  return db.transaction(async (tx) => {
    await tx.exec(
      `SELECT pg_advisory_xact_lock(${MIGRATION_LOCK});
       CREATE TABLE IF NOT EXISTS schema_migrations (
         version INTEGER PRIMARY KEY,
         name TEXT NOT NULL,
         applied_at TIMESTAMPTZ NOT NULL
       );`,
    );
    const done = new Set((await tx.query("SELECT version FROM schema_migrations")).map((r) => toInt(r.version)));
    const current = Math.max(0, ...done);
    if (current > known) throw new Error(`user database schema is v${current}, newer than this server (v${known}); refusing to start`);
    const applied: number[] = [];
    for (const m of [...migrations].sort((a, b) => a.version - b.version)) {
      if (done.has(m.version)) continue;
      await tx.exec(m.up);
      await tx.query("INSERT INTO schema_migrations (version, name, applied_at) VALUES ($1, $2, $3::timestamptz)", [
        m.version,
        m.name,
        iso(now()),
      ]);
      applied.push(m.version);
    }
    return { applied, version: Math.max(current, ...applied) };
  });
}
